function validate([slots1, slots2, duration]) {
  for (const [name, slots] of [['slots1', slots1], ['slots2', slots2]]) {
    if (!Array.isArray(slots) || slots.length < 1 || slots.length > 10000) return `${name} needs 1 to 10^4 slots.`;
    for (const slot of slots) {
      if (!Array.isArray(slot) || slot.length !== 2 || !slot.every(Number.isInteger)) return `Each slot in ${name} is a pair [start, end] of integers.`;
      if (slot[0] < 0 || slot[1] > 1e9) return `Times in ${name} are between 0 and 10^9.`;
      if (slot[0] >= slot[1]) return `Each slot in ${name} must start before it ends.`;
    }
    const sorted = slots.slice().sort((a, b) => a[0] - b[0]);
    for (let k = 1; k < sorted.length; k++) {
      if (sorted[k][0] <= sorted[k - 1][1]) return `Two slots in ${name} touch or overlap.`;
    }
  }
  if (!Number.isInteger(duration) || duration < 1 || duration > 1e6) return 'duration is between 1 and 10^6.';
  return null;
}

