function minAvailableDuration(slots1, slots2, duration) {
  let best = null;
  for (const [s1, e1] of slots1) {
    for (const [s2, e2] of slots2) {
      const from = s1 > s2 ? s1 : s2;
      const to = e1 < e2 ? e1 : e2;
      if (to - from >= duration && (best === null || from < best)) best = from;
    }
  }
  return best === null ? [] : [best, best + duration];
}

