function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const makeSlots = () => {
    const count = large ? int(1500, 2000) : int(1, 4);
    const gap = large ? 240000 : 6;
    const slots = [];
    let point = int(0, gap) - 1;
    for (let k = 0; k < count; k++) {
      const start = point + 1 + int(0, gap);
      const end = start + 1 + int(0, gap);
      slots.push([start, end]);
      point = end;
    }
    for (let k = slots.length - 1; k > 0; k--) {
      const r = int(0, k);
      const t = slots[k]; slots[k] = slots[r]; slots[r] = t;
    }
    return slots;
  };
  const slots1 = makeSlots();
  const slots2 = makeSlots();
  const duration = large ? int(1, 150000) : int(1, 6);
  return [slots1, slots2, duration];
}
